export type Language = "en" | "es" | "zh" | "vi" | "ar" | "ko" | "ur" | "am" | "fr" | "hi";
// Order shown in the language picker: English, then the languages most spoken in
// Virginia homes (U.S. Census ACS), then Hindi. dir drives right-to-left layout.
export const languages = [{id:"en",name:"English",sub:"English",speech:"en-US",dir:"ltr"},{id:"es",name:"Español",sub:"Spanish",speech:"es-US",dir:"ltr"},{id:"zh",name:"中文（简体）",sub:"Chinese (Simplified)",speech:"zh-CN",dir:"ltr"},{id:"vi",name:"Tiếng Việt",sub:"Vietnamese",speech:"vi-VN",dir:"ltr"},{id:"ar",name:"العربية",sub:"Arabic",speech:"ar-SA",dir:"rtl"},{id:"ko",name:"한국어",sub:"Korean",speech:"ko-KR",dir:"ltr"},{id:"ur",name:"اردو",sub:"Urdu",speech:"ur-PK",dir:"rtl"},{id:"am",name:"አማርኛ",sub:"Amharic",speech:"am-ET",dir:"ltr"},{id:"fr",name:"Français",sub:"French",speech:"fr-FR",dir:"ltr"},{id:"hi",name:"हिन्दी",sub:"Hindi",speech:"hi-IN",dir:"ltr"}] as const;
export const isLanguage=(v:unknown):v is Language=>languages.some(l=>l.id===v);
export const languageInfo=(id:Language)=>languages.find(l=>l.id===id)||languages[0];
